import React from 'react';

// ============================================================================
// Piece/board theme system.
//
// Four themes, all with zero licensing obligations. react-chessboard's own
// built-in piece rendering ("classic") has been dropped entirely - every
// theme in this file is now one of our own custom sets, so there's no
// fallback-to-default-look path left in getCustomPieces/getBoardColors.
//   - 'named': not artwork at all - just each piece's lowercase name
//     ("pawn", "king", ...) set as an SVG <text> element. No source/license
//     to track since there's no art, and it reuses the same
//     STENCIL_WHITE/STENCIL_BLACK palette as Stencil/Rounded.
//   - 'stencil': a bold flat silhouette set sourced from "Chess symbols set"
//     by Igor Krizanovskij (published anonymously), via OpenClipart -
//     https://openclipart.org/detail/24125/chess-symbols-set--by-anonymous-24125
//     License: Creative Commons Public Domain (CC0-equivalent) - reproduction,
//     distribution, and derivative works all explicitly permitted, no
//     attribution required (credited here anyway as good practice).
//   - 'bold': a thick rounded set sourced from "DG-RA Style Chess Pieces
//     Set 2.0" by DG-RA, via freesvg.org -
//     https://freesvg.org/dg-ra-style-chess-pieces
//     License: Creative Commons 0 (CC0 / public domain) - copying, modifying,
//     distributing, and commercial use all explicitly permitted, no
//     permission or attribution required (credited here anyway as good
//     practice). Unlike Stencil, each piece keeps its own baked-in fill
//     colors from the source art (cream body / black outline for white,
//     black body / white outline for black) rather than taking an external
//     color prop, since the source already draws each piece fully colored.
//   - 'rounded': a friendly single-path set ("Chess Set" by akiross), via
//     OpenClipart - https://openclipart.org/detail/11373/chess-set-by-akiross
//     License: Creative Commons Public Domain (CC0-equivalent) - reproduction,
//     distribution, and derivative works all explicitly permitted, no
//     attribution required (credited here anyway as good practice). Same
//     single-path-plus-external-colors shape as Stencil (reuses the same
//     STENCIL_WHITE/STENCIL_BLACK palette), just a different silhouette -
//     rounded caps and a shield-shaped rook instead of Stencil's flat bevel.
//
// A previous version of this file also shipped Wood/Green/Blue/Gray/Quill
// themes built on Cburnett-derived geometry (CC BY-SA 3.0 - free to use,
// but requiring attribution + share-alike on redistribution). Those were
// intentionally dropped so nothing in this file carries any licensing
// obligation at all. If a broader "basic tier" gets rebuilt later, do it
// from equally clean sources (public domain / MIT / CC0) the way Stencil,
// Bold, and Rounded were sourced.
//
// Every custom piece shares ONE 120x140 viewBox so it scales identically
// inside react-chessboard's square box, on a shared baseline (bottom edge
// at local y=134, horizontally centered at x=60).
// ============================================================================

export type PieceThemeName = 'stencil' | 'bold' | 'rounded' | 'named';

export const PIECE_THEME_LIST: { id: PieceThemeName; label: string }[] = [
    { id: 'stencil', label: 'Stencil' },
    { id: 'bold', label: 'Bold' },
    { id: 'rounded', label: 'Rounded' },
    { id: 'named', label: 'Named' },
];

type PieceComponent = (props: { squareWidth?: number; isDragging?: boolean }) => React.ReactElement;
type PieceColors = { fill: string; stroke: string };

// Stencil palette - bold flat silhouette, no accent lines needed.
const STENCIL_WHITE: PieceColors = { fill: '#f5f5f0', stroke: '#1a1a1a' };
const STENCIL_BLACK: PieceColors = { fill: '#1a1a1a', stroke: '#000000' };

// Each piece keeps its own natural proportions from the source art (the
// bishop is drawn tallest, pawn narrowest, etc.) - one shared SCALE maps the
// tallest piece to a consistent height inside our 120x140 box, and a
// per-piece translate centers each one on the shared x=60 / baseline y=134.
const STENCIL_SCALE = 1.335559;
const STENCIL_STROKE = 2 / STENCIL_SCALE;

type StencilSpec = { d: string; transform: string };

