function boldPieceSvg(key: string): PieceComponent {
    const spec = BOLD_GEOMETRY[key];
    return ({ squareWidth }) => (
        <svg width={squareWidth} height={squareWidth} viewBox="0 0 120 140">
            <g transform={spec.transform} dangerouslySetInnerHTML={{ __html: spec.svg }} />
        </svg>
    );
}

const boldPieces: Record<string, PieceComponent> = {
    wP: boldPieceSvg('wP'),
    wN: boldPieceSvg('wN'),
    wB: boldPieceSvg('wB'),
    wR: boldPieceSvg('wR'),
    wQ: boldPieceSvg('wQ'),
    wK: boldPieceSvg('wK'),
    bP: boldPieceSvg('bP'),
    bN: boldPieceSvg('bN'),
    bB: boldPieceSvg('bB'),
    bR: boldPieceSvg('bR'),
    bQ: boldPieceSvg('bQ'),
    bK: boldPieceSvg('bK'),
};

