const ROUNDED_SCALE = 0.841739;
const ROUNDED_STROKE = 2 / ROUNDED_SCALE;

function roundedPieceSvg(piece: 'P' | 'N' | 'B' | 'R' | 'Q' | 'K', colors: PieceColors): PieceComponent {
    const spec = ROUNDED_GEOMETRY[piece];
    return ({ squareWidth }) => (
        <svg width={squareWidth} height={squareWidth} viewBox="0 0 120 140">
            <g transform={spec.transform}>
                <path d={spec.d} fill={colors.fill} stroke={colors.stroke} strokeWidth={ROUNDED_STROKE} strokeLinejoin="round" />
            </g>
        </svg>
    );
}

const roundedPieces: Record<string, PieceComponent> = {
    wP: roundedPieceSvg('P', STENCIL_WHITE),
    wN: roundedPieceSvg('N', STENCIL_WHITE),
    wB: roundedPieceSvg('B', STENCIL_WHITE),
    wR: roundedPieceSvg('R', STENCIL_WHITE),
    wQ: roundedPieceSvg('Q', STENCIL_WHITE),
    wK: roundedPieceSvg('K', STENCIL_WHITE),
    bP: roundedPieceSvg('P', STENCIL_BLACK),
    bN: roundedPieceSvg('N', STENCIL_BLACK),
    bB: roundedPieceSvg('B', STENCIL_BLACK),
    bR: roundedPieceSvg('R', STENCIL_BLACK),
    bQ: roundedPieceSvg('Q', STENCIL_BLACK),
    bK: roundedPieceSvg('K', STENCIL_BLACK),
};

// Named set - no artwork, just each piece's lowercase name set as text.
// textLength+lengthAdjust stretches/compresses every label ("pawn" through
// "knight") to the same on-square width so they all read as one consistent
// set regardless of word length, rather than "pawn" looking tiny next to a
// cramped "bishop". paintOrder="stroke" draws the outline behind the fill,
// like a simple text-outline effect, so labels stay legible on both light
// and dark squares.
const NAMED_LABELS: Record<'P' | 'N' | 'B' | 'R' | 'Q' | 'K', string> = {
    P: 'pawn',
    N: 'knight',
    B: 'bishop',
    R: 'rook',
    Q: 'queen',
    K: 'king',
};

const NAMED_TEXT_WIDTH = 104;

function namedPieceSvg(piece: 'P' | 'N' | 'B' | 'R' | 'Q' | 'K', colors: PieceColors): PieceComponent {
    const label = NAMED_LABELS[piece];
    return ({ squareWidth }) => (
        <svg width={squareWidth} height={squareWidth} viewBox="0 0 120 140">
            <text
                x={60}
                y={70}
                textAnchor="middle"
                dominantBaseline="middle"
                textLength={NAMED_TEXT_WIDTH}
                lengthAdjust="spacingAndGlyphs"
                fontFamily="Georgia, 'Times New Roman', serif"
                fontWeight={700}
                fontSize={24}
                fill={colors.fill}
                stroke={colors.stroke}
                strokeWidth={3}
                strokeLinejoin="round"
                paintOrder="stroke"
            >
                {label}
            </text>
        </svg>
    );
}

const namedPieces: Record<string, PieceComponent> = {
    wP: namedPieceSvg('P', STENCIL_WHITE),
    wN: namedPieceSvg('N', STENCIL_WHITE),
    wB: namedPieceSvg('B', STENCIL_WHITE),
    wR: namedPieceSvg('R', STENCIL_WHITE),
    wQ: namedPieceSvg('Q', STENCIL_WHITE),
    wK: namedPieceSvg('K', STENCIL_WHITE),
    bP: namedPieceSvg('P', STENCIL_BLACK),
    bN: namedPieceSvg('N', STENCIL_BLACK),
    bB: namedPieceSvg('B', STENCIL_BLACK),
    bR: namedPieceSvg('R', STENCIL_BLACK),
    bQ: namedPieceSvg('Q', STENCIL_BLACK),
    bK: namedPieceSvg('K', STENCIL_BLACK),
};

// Board color presets. The board is the lit object in the Obsidian system,
// so it is a cool slate rather than react-chessboard's default warm wood -
// a tan board against a near-black cool UI read as two different designs.
// These values were picked for piece legibility, not just for looks: the
// worst-case contrast here is 2.36:1 (white piece on a light square), which
// is better than the wood board it replaces (1.29:1 in the same spot).
const SLATE_BOARD_COLORS = { light: '#9aa5b1', dark: '#586574' };

const CUSTOM_PIECES: Record<PieceThemeName, Record<string, PieceComponent>> = {
    stencil: stencilPieces,
    bold: boldPieces,
    rounded: roundedPieces,
    named: namedPieces,
};

export function getCustomPieces(theme: PieceThemeName): Record<string, PieceComponent> {
    return CUSTOM_PIECES[theme];
}

export function getBoardColors(theme: PieceThemeName): { light: string; dark: string } {
    void theme; // every theme currently uses the same board colors
    return SLATE_BOARD_COLORS;
}
